/**
 * The single closest real species for every Pokémon on /pokemon-animals, keyed
 * by Pokémon slug. Each `species` is a published `/animals/<slug>` page with
 * catalog artwork, so the directory can link and illustrate every row, and
 * `animal` is that page's species name. Designs built on objects, plants or
 * myth are `broad` and name the real animal that comes nearest.
 *
 * `src/lib/pokemon-animal-matches.test.ts` checks every slug is published and
 * every name still matches its page.
 */
export type PokemonAnimalMatch = {
    species: string;
    animal: string;
    confidence: "strong" | "medium" | "broad";
    note: string;
    /** Secondary species the design also evokes, shown after the primary. */
    also?: string[];
};

